def investigate(context, acquire):
    receipts = acquire('history')
    if not receipts:
        return {'value': None, 'unresolved': True}

    def simulate(actions, put_mode, channel_mode, trigger):
        # committed state
        committed = {}
        # per-connection transaction state: None or dict of pending changes
        tx = {'main': None, 'other': None}
        # counters
        changes = {'main': 0, 'other': 0}
        total = {'main': 0, 'other': 0}
        # trigger log count (unread, but affects total_changes)
        log_count = 0

        def do_put(conn, key, value):
            nonlocal log_count
            # determine current visible state for this connection
            if tx[conn] is not None:
                state = tx[conn]
            else:
                state = committed
            # apply put semantics
            if key in state:
                if put_mode == 'ignore':
                    return 0
                elif put_mode == 'replace':
                    state[key] = value
                    return 1
                else:  # update
                    state[key] = value
                    return 1
            else:
                state[key] = value
                return 1

        def do_update(conn, key, value):
            if tx[conn] is not None:
                state = tx[conn]
            else:
                state = committed
            if key in state:
                state[key] = value
                return 1
            return 0

        def do_delete(conn, key):
            if tx[conn] is not None:
                state = tx[conn]
            else:
                state = committed
            if key in state:
                del state[key]
                return 1
            return 0

        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'put':
                n = do_put(conn, act['key'], act['value'])
                changes[conn] += n
                total[conn] += n
                if trigger and n > 0:
                    log_count += 1
                    total[conn] += 1
            elif op == 'update':
                n = do_update(conn, act['key'], act['value'])
                changes[conn] += n
                total[conn] += n
                if trigger and n > 0:
                    log_count += 1
                    total[conn] += 1
            elif op == 'delete':
                n = do_delete(conn, act['key'])
                changes[conn] += n
                total[conn] += n
                if trigger and n > 0:
                    log_count += 1
                    total[conn] += 1
            elif op == 'begin':
                if tx[conn] is None:
                    tx[conn] = dict(committed)
            elif op == 'commit':
                if tx[conn] is not None:
                    committed.clear()
                    committed.update(tx[conn])
                    tx[conn] = None
            elif op == 'rollback':
                if tx[conn] is not None:
                    tx[conn] = None

        if channel_mode == 'changes':
            ch = changes['main']
        elif channel_mode == 'total_main':
            ch = total['main']
        else:
            ch = total['main'] + total['other']
        return ch, len(committed), sum(committed.values())

    put_modes = ['ignore', 'replace', 'update']
    channel_modes = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    candidates = []
    for pm in put_modes:
        for cm in channel_modes:
            for tr in triggers:
                ok = True
                for r in receipts:
                    ch, cc, cs = simulate(r['actions'], pm, cm, tr)
                    obs = r['observed']
                    if ch != obs['channel'] or cc != obs['committed_count'] or cs != obs['committed_sum']:
                        ok = False
                        break
                if ok:
                    candidates.append((pm, cm, tr))

    if not candidates:
        return {'value': None, 'unresolved': True}

    goal = context.get('goal')
    actions = context.get('actions', [])
    results = set()
    for pm, cm, tr in candidates:
        ch, cc, cs = simulate(actions, pm, cm, tr)
        if goal == 'channel':
            results.add(ch)
        elif goal == 'committed_count':
            results.add(cc)
        elif goal == 'committed_sum':
            results.add(cs)
        else:
            return {'value': None, 'unresolved': True}

    if len(results) == 1:
        return {'value': results.pop(), 'unresolved': False}
    return {'value': None, 'unresolved': True}

