def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    goal = context.get("goal", "channel")
    actions = context.get("actions", [])

    def simulate_full(seq_actions, strat, trig, chan_mode):
        committed = {}
        m_pend = {}
        o_pend = {}

        m_tot = 0
        o_tot = 0
        m_last = 0

        m_open = False
        o_open = False

        for act in seq_actions:
            op = act['op']
            c = act.get('connection', 'main')
            k = act.get('key')
            v = act.get('value')

            if op == 'begin':
                if c == 'main': 
                    m_open = True
                    m_pend = {}
                else: 
                    o_open = True
                    o_pend = {}
            elif op == 'commit':
                if c == 'main':
                    for pk, pv in m_pend.items():
                        if pv is None: 
                            if pk in committed: del committed[pk]
                        else: 
                            committed[pk] = pv
                    m_pend = {}
                    m_open = False
                else:
                    for pk, pv in o_pend.items():
                        if pv is None: 
                            if pk in committed: del committed[pk]
                        else: 
                            committed[pk] = pv
                    o_pend = {}
                    o_open = False
            elif op == 'rollback':
                if c == 'main': 
                    m_pend = {}
                    m_open = False
                else: 
                    o_pend = {}
                    o_open = False
            elif op == 'put':
                curr_val = None
                if c == 'main':
                    if k in m_pend:
                        curr_val = m_pend[k]
                    else:
                        curr_val = committed.get(k)
                else:
                    if k in o_pend:
                        curr_val = o_pend[k]
                    else:
                        curr_val = committed.get(k)

                success = False
                rows_changed = 0
                actual_trig = 0

                if curr_val is None:
                    success = True
                    rows_changed = 1
                    actual_trig = 1
                    if c == 'main': m_pend[k] = v
                    else: o_pend[k] = v
                else:
                    if strat == 'IGNORE':
                        success = False
                        rows_changed = 0
                        actual_trig = 0
                    elif strat == 'REPLACE':
                        success = True
                        rows_changed = 2
                        actual_trig = 1
                        if c == 'main': m_pend[k] = v
                        else: o_pend[k] = v
                    elif strat == 'UPSERT':
                        success = True
                        rows_changed = 1
                        actual_trig = 0
                        if c == 'main': m_pend[k] = v
                        else: o_pend[k] = v

                total_delta = rows_changed + (actual_trig if trig else 0)

                if c == 'main':
                    m_tot += total_delta
                    m_last = total_delta
                else:
                    o_tot += total_delta

        res_count = len(committed)
        res_sum = sum(committed.values())

        ch_val = -1
        if chan_mode == 'MAIN_CHANGES': ch_val = m_last
        elif chan_mode == 'MAIN_TOTAL': ch_val = m_tot
        elif chan_mode == 'SUM_TOTAL': ch_val = m_tot + o_tot

        return ch_val, res_count, res_sum

    strategies = ['IGNORE', 'REPLACE', 'UPSERT']
    triggers = [True, False]
    channels = ['MAIN_CHANGES', 'MAIN_TOTAL', 'SUM_TOTAL']

    valid_configs = []

    for s in strategies:
        for t in triggers:
            for c in channels:
                ok = True
                for rec in history:
                    acts = rec['actions']
                    obs = rec['observed']
                    pred_ch, pred_cnt, pred_sum = simulate_full(acts, s, t, c)

                    if pred_ch != obs['channel'] or pred_cnt != obs['committed_count'] or pred_sum != obs['committed_sum']:
                        ok = False
                        break
                if ok:
                    valid_configs.append((s, t, c))

    if not valid_configs:
        return {"value": None, "unresolved": True}

    predictions = set()
    for s, t, c in valid_configs:
        ch, cnt, sm = simulate_full(actions, s, t, c)
        if goal == 'channel': predictions.add(ch)
        elif goal == 'committed_count': predictions.add(cnt)
        elif goal == 'committed_sum': predictions.add(sm)
        else: return {"value": None, "unresolved": True}

    if len(predictions) == 1:
        return {"value": list(predictions)[0], "unresolved": False}
    else:
        return {"value": None, "unresolved": True}

