                    txn_active = True
                    txn_owner = conn
                    txn_buffer = dict(global_db)
                elif op == "commit":
                    if not txn_active:
                         sim_ok = False; break
                    txn_active = False
                    txn_owner = None
                    txn_buffer = None
                elif op == "rollback":
                    if not txn_active:
                         sim_ok = False; break
                    global_db = txn_buffer
                    txn_active = False
                    txn_owner = None
                    txn_buffer = None
