                if check(put_mode, trigger, channel_mode):
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = []
    for put_mode, trigger, channel_mode in candidates:
        ch, cnt, sm = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            results.append(ch)
        elif goal == "committed_count":
            results.append(cnt)
        elif goal == "committed_sum":
            results.append(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(set(results)) == 1:
        return {"value": results[0], "unresolved": False}
    return {"value": None, "unresolved": True}

def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, trigger, channel_mode):
        committed = {}
        main_pending = {}
        other_pending = {}
        main_tx = False
        other_tx = False
        main_changes = 0
        other_changes = 0
        main_total = 0
        other_total = 0

        def view(conn):
            if conn == "main":
                if main_tx:
                    d = dict(committed)
                    d.update(main_pending)
                    return d
                return committed
            else:
                if other_tx:
                    d = dict(committed)
                    d.update(other_pending)
                    return d
                return committed

        def apply(conn, key, value, mode):
            nonlocal main_changes, other_changes, main_total, other_total
            v = view(conn)
            changes = 0
            if mode == "put":
                if put_mode == "ignore":
                    if key not in v:
                        changes = 1
                elif put_mode == "replace":
                    changes = 1
                else:
                    changes = 1
            elif mode == "update":
                if key in v:
                    changes = 1
            elif mode == "delete":
                if key in v:
                    changes = 1
            if changes == 0:
                if conn == "main":
                    main_changes = 0
                else:
                    other_changes = 0
                return
            if conn == "main":
                if main_tx:
                    if mode == "delete":
                        if key in main_pending:
                            del main_pending[key]
                        else:
                            main_pending[key] = None
                    else:
                        main_pending[key] = value
                else:
                    if mode == "delete":
                        if key in committed:
                            del committed[key]
                    else:
                        committed[key] = value
                main_changes = changes
                main_total += changes
                if trigger and mode == "put":
                    main_total += 1
            else:
                if other_tx:
                    if mode == "delete":
                        if key in other_pending:
                            del other_pending[key]
                        else:
                            other_pending[key] = None
                    else:
                        other_pending[key] = value
                else:
                    if mode == "delete":
                        if key in committed:
                            del committed[key]
                    else:
                        committed[key] = value
                other_changes = changes
                other_total += changes
                if trigger and mode == "put":
                    other_total += 1

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                apply(conn, act["key"], act["value"], "put")
            elif op == "update":
                apply(conn, act["key"], act["value"], "update")
            elif op == "delete":
                apply(conn, act["key"], None, "delete")
            elif op == "begin":
                if conn == "main":
                    main_tx = True
                    main_pending = {}
                else:
                    other_tx = True
                    other_pending = {}
            elif op == "commit":
                if conn == "main":
                    for k, v in main_pending.items():
                        if v is None:
                            if k in committed:
                                del committed[k]
                        else:
                            committed[k] = v
                    main_pending = {}
                    main_tx = False
                else:
                    for k, v in other_pending.items():
                        if v is None:
                            if k in committed:
                                del committed[k]
                        else:
                            committed[k] = v
                    other_pending = {}
                    other_tx = False
            elif op == "rollback":
                if conn == "main":
                    main_pending = {}
                    main_tx = False
                else:
                    other_pending = {}
                    other_tx = False

        if channel_mode == "main_changes":
            channel = main_changes
        elif channel_mode == "main_total":
            channel = main_total
        else:
            channel = main_total + other_total

        count = len(committed)
        total = sum(committed.values())
        return channel, count, total

    def check(put_mode, trigger, channel_mode):
        for rec in history:
            actions = rec["actions"]
            obs = rec["observed"]
            ch, cnt, sm = simulate(actions, put_mode, trigger, channel_mode)
            if ch != obs["channel"] or cnt != obs["committed_count"] or sm != obs["committed_sum"]:
                return False
        return True

    candidates = []
    for put_mode in ["ignore", "replace", "upsert"]:
        for trigger in [False, True]:
            for channel_mode in ["main_changes", "main_total", "both_total"]:
                if check(put_mode, trigger, channel_mode):
                    candidates.append((put_mode, trigger, channel_mode))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = []
    for put_mode, trigger, channel_mode in candidates:
        ch, cnt, sm = simulate(actions, put_mode, trigger, channel_mode)
        if goal == "channel":
            results.append(ch)
        elif goal == "committed_count":
            results.append(cnt)
        elif goal == "committed_sum":
            results.append(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(set(results)) == 1:
        return {"value": results[0], "unresolved": False}
    return {"value": None, "unresolved": True}
